import type {
  CacheMode,
  CacheKindStats,
  CacheMemoryStats,
  CacheOptions,
  CacheStats,
  CssInput,
  Node,
  RendererOptions,
} from "@takumi-rs/helpers";
import type { Properties } from "csstype";

export type {
  ContainerNode,
  ImageNode,
  NodeMetadata,
  RgbaImage,
  TextNode,
} from "@takumi-rs/helpers";

export type {
  CacheMode,
  CacheKindStats,
  CacheMemoryStats,
  CacheOptions,
  CacheStats,
  CssInput,
  Node,
  RendererOptions,
};

export type ByteBuf = Uint8Array | ArrayBuffer | Buffer;

export interface FontDetails {
  /**
   * The name of the font. If not provided, the name in the font file will be used.
   */
  name?: string;
  /**
   * The font data.
   */
  data: ByteBuf;
  /**
   * The weight of the font. If not provided, the weight in the font file will be used.
   */
  weight?: number;
  /**
   * The style of the font. If not provided, the style in the font file will be used.
   */
  style?: "normal" | "italic" | "oblique" | `oblique ${number}deg` | (string & {});
  /**
   * Inclusive codepoint ranges the font serves, as `@font-face` `unicode-range`. Register each
   * subset of a family under the same `name` with its own ranges.
   */
  unicodeRange?: [number, number][];
  /** @deprecated Register under `name` with `unicodeRange` instead. */
  subsetOf?: string;
  /** @deprecated Ignored; `unicodeRange` decides which subset serves a codepoint. */
  subsetRank?: number;
  /**
   * CSS generic family keyword this font resolves for, so stacks ending in e.g.
   * `monospace` reach it without naming the family.
   */
  generic?:
    | "serif"
    | "sans-serif"
    | "monospace"
    | "cursive"
    | "fantasy"
    | "system-ui"
    | "ui-serif"
    | "ui-sans-serif"
    | "ui-monospace"
    | "ui-rounded"
    | "emoji"
    | "math"
    | "fangsong";
}

export type Font = FontDetails | ByteBuf;

/** A font of a render's `fonts` list, described before its bytes arrive. */
type ListedFont = Pick<FontDetails, "name" | "weight" | "style" | "unicodeRange"> & { key: string };

/** @deprecated Use a `{ keyframes, steps }` entry in `css` instead. Will be removed in v3. */
export type KeyframesMap = Record<string, Record<string, Properties>>;
/** @deprecated Use a `{ keyframes, steps }` entry in `css` instead. Will be removed in v3. */
export type KeyframesRuleList = {
  name: string;
  keyframes: {
    offsets: number[];
    declarations: Record<string, Properties>;
  }[];
}[];
/** @deprecated Use a `{ keyframes, steps }` entry in `css` instead. Will be removed in v3. */
export type Keyframes = KeyframesMap | KeyframesRuleList;

/** Output format for animated images. */
export type AnimationOutputFormat = "webp" | "apng" | "gif";

export type DitheringAlgorithm = "none" | "ordered-bayer" | "floyd-steinberg";

/** Cache policy for a decoded image. Defaults to `"auto"`. */
export type ImageCacheMode = "auto" | "none";

/** An image source with its URL and raw data. */
export interface ImageSource {
  /** The source URL of the image. */
  src: string;
  /** The raw image data (Uint8Array or ArrayBuffer). */
  data: Uint8Array | ArrayBuffer;
  /** Cache policy for the decoded image. Defaults to `"auto"`. */
  cache?: ImageCacheMode;
}

/** Output format for static images. */
export type OutputFormat = "webp" | "png" | "jpeg" | "ico" | "raw";

/** @internal The fonts one render sees, by the keys of its `fonts` list in order and the `@font-face` files and optional fonts that failed to load. */
type FontScope = {
  listed?: Array<string>;
  failed?: Array<string>;
};

/** Options for rendering a sequential scene animation. */
export interface RenderAnimationOptions {
  /** The scenes to render sequentially. */
  scenes: Array<AnimationScene>;
  /** Whether to draw debug borders around layout elements. */
  drawDebugBorder?: boolean;
  /** The width of each frame in pixels. */
  width: number;
  /** The height of each frame in pixels. */
  height: number;
  /** The output animation format (WebP, APNG, or GIF). */
  format?: AnimationOutputFormat;
  /**
   * The quality of lossy WebP (0-100). Ignored for APNG and GIF, and when
   * `lossless` is set.
   */
  quality?: number;
  /**
   * Encode WebP losslessly. Defaults to lossless when neither `quality` nor
   * `lossless` is given. Ignored for APNG and GIF.
   */
  lossless?: boolean;
  /** Frames per second for timeline sampling. */
  fps: number;
  /** Images keyed by `src`, each carrying raw bytes. */
  images?: Array<ImageSource>;
  /**
   * CSS to apply before rendering: stylesheet text, or a rule written as an
   * object.
   */
  css?: CssInput[];
  /** @deprecated Use `css` instead. Will be removed in v3. */
  stylesheets?: Array<string>;
  /** @deprecated Use a `{ keyframes, steps }` entry in `css` instead. Will be removed in v3. */
  keyframes?: Keyframes;
  /**
   * The device pixel ratio.
   * @default 1.0
   */
  devicePixelRatio?: number;
  /**
   * Per-render font stack: ordered family names used as the fallback chain.
   * Defaults to all registered families in registration order.
   */
  fontFamilies?: Array<string>;
  /** @internal The fonts the render lists and the ones that failed to load. */
  fontScope?: FontScope;
  /** Default BCP-47 language applied to the root, inherited by nodes without their own lang. */
  lang?: string;
}

/** Options for rendering an image. */
export interface RenderOptions {
  /** The width of the image. If not provided, the width will be automatically calculated based on the content. */
  width?: number;
  /** The height of the image. If not provided, the height will be automatically calculated based on the content. */
  height?: number;
  /** The format of the image. */
  format?: OutputFormat;
  /**
   * The quality of lossy formats (0-100). For JPEG; for WebP it selects lossy
   * encoding unless `lossless` is set.
   */
  quality?: number;
  /**
   * Encode WebP losslessly. Defaults to lossless when neither `quality` nor
   * `lossless` is given.
   */
  lossless?: boolean;
  /** Whether to draw debug borders. */
  drawDebugBorder?: boolean;
  /** Images keyed by `src`, each carrying raw bytes. */
  images?: Array<ImageSource>;
  /**
   * CSS to apply before rendering: stylesheet text, or a rule written as an
   * object.
   */
  css?: CssInput[];
  /** @deprecated Use `css` instead. Will be removed in v3. */
  stylesheets?: Array<string>;
  /** @deprecated Use a `{ keyframes, steps }` entry in `css` instead. Will be removed in v3. */
  keyframes?: Keyframes;
  /**
   * The device pixel ratio.
   * @default 1.0
   */
  devicePixelRatio?: number;
  /** The animation timeline time in milliseconds. */
  timeMs?: number;
  /** Dithers gradient fills before they quantize to 8-bit. */
  dithering?: DitheringAlgorithm;
  /**
   * Per-render font stack: ordered family names used as the fallback chain.
   * Defaults to all registered families in registration order.
   */
  fontFamilies?: Array<string>;
  /** @internal The fonts the render lists and the ones that failed to load. */
  fontScope?: FontScope;
  /** Default BCP-47 language applied to the root, inherited by nodes without their own lang. */
  lang?: string;
}

/**
 * Options for rendering a node tree to an SVG document. SVG is a vector
 * format, so the raster-only knobs (`format`, `quality`, `lossless`,
 * `dithering`, `drawDebugBorder`, `devicePixelRatio`) do not apply.
 */
export interface SvgRenderOptions {
  /** The width of the viewport. If not provided, it is derived from content. */
  width?: number;
  /** The height of the viewport. If not provided, it is derived from content. */
  height?: number;
  /** Images keyed by `src`, each carrying raw bytes. */
  images?: Array<ImageSource>;
  /**
   * CSS to apply before rendering: stylesheet text, or a rule written as an
   * object.
   */
  css?: CssInput[];
  /** @deprecated Use `css` instead. Will be removed in v3. */
  stylesheets?: Array<string>;
  /** @deprecated Use a `{ keyframes, steps }` entry in `css` instead. Will be removed in v3. */
  keyframes?: Keyframes;
  /** The animation timeline time in milliseconds. */
  timeMs?: number;
  /**
   * Per-render font stack: ordered family names used as the fallback chain.
   * Defaults to all registered families in registration order.
   */
  fontFamilies?: Array<string>;
  /** @internal The fonts the render lists and the ones that failed to load. */
  fontScope?: FontScope;
  /** Default BCP-47 language applied to the root, inherited by nodes without their own lang. */
  lang?: string;
}

/**
 * Which binding artifact the generated loader actually loaded: `'native'` for
 * a native addon, otherwise the `platformArchABI` of the WASI flavor. Every
 * flavor napi-rs can build is listed, because `NAPI_RS_NATIVE_LIBRARY_PATH`
 * can point the loader at a WASI artifact this package does not build itself.
 */
export declare const __napiBindingTarget: 'native' | 'wasm32-wasi' | 'wasm32-wasip1'

/** The main renderer for Takumi image rendering engine (Node.js version). */
export declare class Renderer {
  /** Creates a new Renderer instance. */
  constructor(options?: RendererOptions | undefined | null)
  /**
   * Register font into the renderer, under `key` when its loader gives one, returning the
   * families produced. It is never evicted.
   */
  registerFont(fonts: Font, key?: string | null, signal?: AbortSignal): Promise<RegisteredFamily[]>
  /**
   * Registers a font a render's `fonts` list loaded under `key`, its file leased to `lease` and
   * evicted once no lease holds it and the cache needs the room.
   */
  cacheFont(fonts: Font, key: string, lease?: number | null, signal?: AbortSignal): Promise<RegisteredFamily[]>
  /**
   * The families a registration under `key` added, while the renderer holds its file. Leases the
   * file to `lease`, or with `pin` keeps it from eviction for good.
   */
  cachedFonts(key: string, pin: boolean, lease?: number | undefined | null): Array<RegisteredFamily> | null
  /**
   * Loads the `@font-face` file `url` names, as `needs` reported it, leased to `lease` and evicted
   * once no lease holds it and the cache needs the room.
   */
  cacheFontFile(url: string, data: Uint8Array | ArrayBuffer, lease?: number | null, signal?: AbortSignal): Promise<void>
  /**
   * Whether the renderer still holds the `@font-face` file `url`, leasing it to `lease` when it
   * does.
   */
  cachedFontFile(url: string, lease: number): boolean
  /**
   * Opens a set of leases that keeps the font files a render uses from eviction until
   * `releaseFonts`.
   */
  leaseFonts(): number
  /** Releases the leases of the set `lease` names, evicting what no longer fits. */
  releaseFonts(lease: number): void
  /**
   * Forgets the fonts registered under `keys` whose files no render leases, as a font with
   * `cache: "none"` asks once its render settles, returning those keys and the ones nothing is
   * registered under.
   */
  dropFonts(keys: Array<string>): Array<string>
  /** What the renderer's caches hold and how their lookups went since it was created. */
  cacheStats(): CacheStats
  /**
   * Removes every face registered under `family`, each `unicodeRange` subset alike, returning
   * whether it had any.
   */
  unregisterFont(family: string): boolean
  /** Removes every registered font, leaving the bundled fallback font. */
  clearFonts(): void
  /** Renders a node tree, or HTML, into an image buffer asynchronously. */
  render(source: Node | string | { json: string }, options?: RenderOptions, signal?: AbortSignal): Promise<Buffer<ArrayBuffer>>
  /** Renders a node tree, or HTML, into an SVG document string asynchronously. */
  renderSvg(source: Node | string | { json: string }, options?: SvgRenderOptions, signal?: AbortSignal): Promise<string>
  /** Measures a node tree, or HTML, and returns layout information asynchronously. */
  measure(source: Node | string | { json: string }, options?: RenderOptions, signal?: AbortSignal): Promise<MeasuredNode>
  /** Reads what a node tree, or HTML, needs fetched before it renders, asynchronously. */
  needs(source: Node | string | { json: string }, options?: RenderOptions, fonts?: ListedFont[], signal?: AbortSignal): Promise<RenderNeeds>
  /** Reads what every scene of an animation needs fetched before it renders, asynchronously. */
  animationNeeds(options: RenderAnimationOptions, fonts?: ListedFont[], signal?: AbortSignal): Promise<RenderNeeds>
  /** Renders a sequential scene animation into a buffer asynchronously. */
  renderAnimation(options: RenderAnimationOptions, signal?: AbortSignal): Promise<Buffer<ArrayBuffer>>
}

/** Represents a single scene in a sequential animation timeline. */
export interface AnimationScene {
  /** The node tree to render for this scene, the `{ json }` text of one, or HTML markup. */
  node: Node | string | { json: string }
  /** The duration of this scene in milliseconds. */
  durationMs: number
}

/** A declaration or at-rule the style parser dropped. */
export interface IgnoredDeclaration {
  /** The property as written, or the at-rule's name with its `@`. */
  property: string
  /** The value as written, or the at-rule's prelude. */
  value: string
  /** Why it was dropped. */
  reason: "unknown-property" | "invalid-value" | "unknown-at-rule"
  /** Where it was written. */
  origin: "style-attribute" | "style-sheet" | "style-object"
}

/** Represents a node that has been measured, including its layout information. */
export interface MeasuredNode {
  /** The measured width of the node. */
  width: number
  /** The measured height of the node. */
  height: number
  /** The transformation matrix of the node. */
  transform: [number, number, number, number, number, number]
  /** The children of the node. */
  children: Array<MeasuredNode>
  /** The text runs within the node. */
  runs: Array<MeasuredTextRun>
}

/** Represents a single run of text in a measured node. */
export interface MeasuredTextRun {
  /** The text content of the run. */
  text: string
  /** The inline x-coordinate of the run. */
  x: number
  /** The inline y-coordinate of the run. */
  y: number
  /** The width of the run. */
  width: number
  /** The height of the run. */
  height: number
}

/** A single face within a `RegisteredFamily`. */
export interface RegisteredFace {
  /** Weight class, typically `1`–`1000`. */
  weight: number
  /** CSS `font-style` value (`normal`, `italic`, or `oblique [<angle>deg]`). */
  style: string
  /** Width as a percentage of normal (e.g. `100`). */
  width: number
  /** Index of the face within its source collection. */
  index: number
}

/** A font family produced by `registerFont`, with the faces it contains. */
export interface RegisteredFamily {
  /** Family name as stored by the font system (normalized; reflects any override). */
  name: string
  /** Faces registered under this family. */
  faces: Array<RegisteredFace>
}

/** The images a node tree looks up by URL and the listed fonts the render loads. */
export interface RenderNeeds {
  /** The image URLs the tree looks up, except `data:` URIs and inline SVG, sorted. */
  images: Array<string>
  /** The ids of the listed fonts the render loads, sorted. */
  fonts: Array<number>
  /** The `@font-face` file URLs the render loads, sorted. */
  fontFiles: Array<string>
  /** The URLs of the loaded `@font-face` files the render draws with, sorted. */
  loadedFontFiles: Array<string>
  /** The characters no font in their fallback chain draws, each once in document order. */
  missingCharacters: Array<string>
  /** The families `font-family` or `fontFamilies` names that no font provides, each once. */
  unresolvedFamilies: Array<string>
  /** The declarations and at-rules the style parser dropped, each once. */
  ignoredDeclarations: Array<IgnoredDeclaration>
}

/**
 * Keeps no glyphs in each `Renderer` created after this call when `bytes` is `0`, and glyphs again
 * otherwise. Glyphs share the renderer's `cache.maxBytes` with every other kind of data.
 *
 * @deprecated Use `new Renderer({ cache: { glyphs: "none" } })`.
 */
export declare function setGlyphCacheMaxBytes(bytes: number): void
